28: /// Generates a massive, continuous synthetic trajectory containing `point_count` points.
29: ///
30: /// Features:
31: /// - 10 Hz telemetry cadence (dt = 0.1s).
32: /// - Realistic Archimedean spiral geospatial trajectory starting in Seattle (47.6062° N, -122.3321° W).
33: /// - Complete flight phases: ground idle, takeoff, climb, cruise, turns, high-speed dash, descent, flare, landing.
34: /// - 4-cell smart battery gradual discharge (100% -> 15%) with cell balance metrics.
35: /// - Multiple landmark events: Takeoff, Mode Changes, Warnings, MaxAltitude, MaxSpeed, RTH, Landing.
36: fn generate_massive_trajectory(point_count: usize) -> FlightDataset {
37:     assert!(point_count >= 1000, "Point count should be >= 1000 for realistic flight phases");
38: 
39:     let base_lat = 47.606212;
40:     let base_lon = -122.332145;
41:     let takeoff_alt_msl = 125.40;
42:     let base_time_ms = 1_729_000_000_000i64;
43: 
44:     let takeoff_idx = 100;
45:     let landing_idx = point_count.saturating_sub(100);
46:     let cruise_start = point_count / 10;
47:     let rth_idx = point_count * 8 / 10;
48: 
49:     let mut points = Vec::with_capacity(point_count);
50:     let mut events = Vec::new();
51: 
52:     let mut max_alt_agl = 0.0f64;
53:     let mut max_alt_msl = takeoff_alt_msl;
54:     let mut max_h_speed = 0.0f64;
55:     let mut max_v_speed = 0.0f64;
56:     let mut max_descent = 0.0f64;
57:     let mut total_distance = 0.0f64;
58: 
59:     let mut prev_lat = base_lat;
60:     let mut prev_lon = base_lon;
61: 
62:     for i in 0..point_count {
63:         let elapsed_s = i as f64 * 0.1;
64:         let is_motor_on = i >= takeoff_idx && i <= landing_idx;
65:         let fly_time_s = if is_motor_on {
66:             (i - takeoff_idx) as f64 * 0.1
67:         } else {
68:             0.0
69:         };
70: 
71:         // Altitude profile: climb to 350m AGL, cruise with gentle oscillation, then descend
72:         let (agl, vel_d) = if i < takeoff_idx {
73:             (0.0, 0.0)
74:         } else if i < cruise_start {
75:             let frac = (i - takeoff_idx) as f64 / (cruise_start - takeoff_idx) as f64;
76:             (frac * 350.0, -1.5)
77:         } else if i < rth_idx {
78:             let phase = ((i - cruise_start) as f64 * 0.005).sin();
79:             (350.0 + phase * 25.0, phase * 0.5)
80:         } else if i <= landing_idx {
81:             let frac = 1.0 - (i - rth_idx) as f64 / (landing_idx - rth_idx) as f64;
82:             (frac * 350.0, 1.2)
83:         } else {
84:             (0.0, 0.0)
85:         };
86: 
87:         let alt_msl = takeoff_alt_msl + agl;
88:         let climb_rate = -vel_d;
89: 
90:         // Kinematics and attitude: expanding spiral path
91:         let angle_rad = (i as f64 * 0.002) % (2.0 * std::f64::consts::PI);
92:         let radius_deg = (i as f64 * 0.0000008).min(0.05);
93:         let lat = base_lat + radius_deg * angle_rad.cos();
94:         let lon = base_lon + (radius_deg * angle_rad.sin()) / base_lat.to_radians().cos();
95: 
96:         let yaw_deg = (angle_rad.to_degrees() + 90.0) % 360.0;
97:         let heading_deg = if yaw_deg < 0.0 { yaw_deg + 360.0 } else { yaw_deg };
98: 
99:         let h_speed = if is_motor_on {
100:             12.0 + 3.0 * (i as f64 * 0.01).sin()
101:         } else {
102:             0.0
103:         };
104:         let speed_3d = (h_speed * h_speed + vel_d * vel_d).sqrt();
105:         let rad = heading_deg.to_radians();
106:         let vel_n = h_speed * rad.cos();
107:         let vel_e = h_speed * rad.sin();
108: 
109:         // Accumulate distance
110:         if i > 0 {
111:             let d = flightreader_core::geo::geodesic_distance(prev_lat, prev_lon, lat, lon);
112:             if d > 0.0 && d < 500.0 {
113:                 total_distance += d;
114:             }
115:         }
116:         prev_lat = lat;
117:         prev_lon = lon;
118: 
119:         if agl > max_alt_agl { max_alt_agl = agl; }
120:         if alt_msl > max_alt_msl { max_alt_msl = alt_msl; }
121:         if h_speed > max_h_speed { max_h_speed = h_speed; }
122:         if climb_rate > max_v_speed { max_v_speed = climb_rate; }
123:         if vel_d > max_descent { max_descent = vel_d; }
124: 
125:         let timestamp_utc_ms = base_time_ms + (elapsed_s * 1000.0).round() as i64;
126:         let timestamp_iso8601 = chrono::DateTime::from_timestamp_millis(timestamp_utc_ms)
127:             .map(|dt| dt.to_rfc3339_opts(chrono::SecondsFormat::Millis, true))
128:             .unwrap_or_else(|| "1970-01-01T00:00:00.000Z".to_string());
129: 
130:         // Battery: 100% down to 15%
131:         let progress = i as f64 / point_count as f64;
132:         let battery_pct = (100.0 - progress * 85.0).round() as u8;
133:         let pack_v = 16.8 - progress * 2.8;
134:         let cell_v_mv = ((pack_v / 4.0) * 1000.0).round() as u16;
135: 
136:         let flight_mode = if i < takeoff_idx {
137:             "P-GPS".to_string()
138:         } else if i >= rth_idx && i <= landing_idx {
139:             "Auto-RTH".to_string()
140:         } else if i > landing_idx {
141:             "AutoLanding".to_string()
142:         } else {
143:             "P-GPS".to_string()
144:         };
145: 
146:         let app_warning = if i == point_count / 2 {
147:             Some("High Wind Warning. Fly with caution.".to_string())
148:         } else {
149:             None
150:         };
151: 
152:         let is_failsafe_active = i >= rth_idx && i <= landing_idx;
153: 
154:         let pt = TelemetryPoint {
155:             index: i,
156:             timestamp_utc_ms,
157:             timestamp_iso8601,
158:             elapsed_s,
159:             fly_time_s,
160:             latitude: lat,
161:             longitude: lon,
162:             altitude_msl: alt_msl,
163:             altitude_agl: agl,
164:             altitude_baro: agl,
165:             vps_height_m: if agl < 5.0 { Some(agl) } else { None },
166:             ground_speed_mps: h_speed,
167:             speed_3d_mps: speed_3d,
168:             climb_rate_mps: climb_rate,
169:             vel_n,
170:             vel_e,
171:             vel_d,
172:             course_deg: heading_deg,
173:             pitch_deg: if h_speed > 5.0 { -10.5 } else { 0.0 },
174:             roll_deg: if h_speed > 5.0 { 2.1 } else { 0.0 },
175:             yaw_deg,
176:             heading_deg,
177:             gimbal_pitch_deg: -30.0,
178:             gimbal_roll_deg: 0.0,
179:             gimbal_yaw_deg: 0.0,
180:             gimbal_mode: "Follow Yaw".to_string(),
181:             rc_aileron: 0.05 * (i as f64 * 0.1).sin(),
182:             rc_elevator: 0.25,
183:             rc_throttle: if is_motor_on { 0.55 } else { 0.0 },
184:             rc_rudder: 0.02 * (i as f64 * 0.05).cos(),
185:             rc_mode_switch: "P".to_string(),
186:             rc_signal_quality: 98,
187:             battery_pct,
188:             battery_voltage_mv: (pack_v * 1000.0).round() as u32,
189:             battery_temp_c: 25.0 + progress * 15.0,
190:             battery_current_a: if is_motor_on { Some(12.4) } else { Some(0.8) },
191:             cell_voltages_mv: vec![cell_v_mv, cell_v_mv.saturating_sub(5), cell_v_mv + 3, cell_v_mv],
192:             cell_deviation_mv: 8,
193:             gps_satellites: 22,
194:             gps_level: 5,
195:             flight_mode,
196:             ground_state: if is_motor_on { "Airborne".to_string() } else { "OnGround".to_string() },
197:             is_motor_on,
198:             is_failsafe_active,
199:             app_warning,
200:             app_tip: None,
201:         };
202:         points.push(pt);
203:     }
